  "excludes.advisoryImmichDb": "يحفظ Immich ألبومات كل صورة ووجوهها وتواريخها في قاعدة بيانات PostgreSQL تعمل في حاوية منفصلة خاصة بها، لذا لا تحتوي هذه النسخة الاحتياطية عليها. الاستعادة من هنا تعيد الصور دون كل ذلك. يفرّغ BombVault حاوية تلك القاعدة تلقائياً حين تُنسخ احتياطياً، فتأكد من أنها مدرجة في جدولك الزمني.",
