  "rcloneRemote.heading": "إضافة وجهة SMB أو WebDAV",
  "rcloneRemote.hint": "يصل إلى مشاركة Windows أو Samba، أو إلى خادم WebDAV مثل Nextcloud، دون تركيبها على المضيف. ينصح restic بعدم الاحتفاظ بمستودع على مشاركة CIFS مركَّبة، وهذا الطريق يتجنب التركيب كليًا. تُسلَّم كلمة المرور إلى rclone ليخزّنها بصيغته الخاصة، ولا تُحفظ أبدًا بنص واضح. لا يُتاح NFS هنا لأنه لا يدعمه أيٌّ من restic وrclone: لاستخدام NFS، ركِّب المجلد المُصدَّر على Unraid ووجِّه مسار نسخ احتياطي إليه.",
