  "dbdump.saveToFolder": "الحفظ في مجلد",
  "dbdump.saveHint": "يكتب النسخة كملف في المجلد المختار على الخادم، بملكية nobody:users حتى تفتحه عبر مشاركة الشبكة. يحتوي الملف على كل الجداول وعلى بصمات كلمات مرور مستخدمي قاعدة البيانات؛ احفظه حيث لا يصل إليه غيرك.",
  "dbdump.saveCancelHint": "الإلغاء يوقف الحفظ ويزيل الملف غير المكتمل.",
