  "mcp.connectHint": "اختر عميلك لإعداد مصمم له: مفتاح يحمل اسمه، والإعدادات التي تنسخها، وخطوة الشهادة التي يحتاجها. أي عميل آخر يتصل عبر عميل آخر. ما يقرؤه المساعد، مثل أسماء العناصر والسجل ورسائل الخطأ، يذهب إلى مزود الذكاء الاصطناعي الذي يقف خلفه، بعد أن يزيل BombVault مسارات المضيف ومواقع المستودعات وبيانات الاعتماد.",
