  "mcp.certPlaceholder": "يستخدم BombVault شهادته الخاصة. توجّه الإعدادات Node.js إليها: نزّل الملف وضع مساره مكان العنصر النائب للشهادة.",
  "mcp.certEnv": "يستخدم BombVault شهادته الخاصة. إذا رفضها {app}، فاضبط متغير البيئة {var} على مسار الملف الذي نزّلته وأعد تشغيل {app}.",
  "mcp.certEnvTip": "اضبطه حيث تضبط متغيرات بيئة المستخدم: في Windows ضمن الإعدادات، النظام، حول، إعدادات النظام المتقدمة، متغيرات البيئة؛ وفي macOS وLinux في ملف تعريف الصدفة؛ وفي الحاوية ضمن إعداداتها مع تركيب الملف داخلها. نزّل الشهادة من جديد كلما أصدر BombVault شهادة جديدة. التطبيق الذي يبدأ من Dock أو Finder على macOS لا يقرأ ملف تعريف الصدفة: من أجله شغّل ‎launchctl setenv {var}‎ مع مسار الملف في Terminal ثم أعد فتح التطبيق، وكرر ذلك بعد كل إعادة تشغيل للـ Mac.",
  "mcp.certSystem": "يستخدم BombVault شهادته الخاصة. إذا رفضها {app}، فأضف الملف الذي نزّلته إلى الشهادات الموثوقة في نظامك وأعد تشغيل {app}.",
  "mcp.certSystemTip": "في Windows، غيّر اسم الملف إلى bombvault-cert.crt، ثم افتحه واختر تثبيت الشهادة، المستخدم الحالي، وضع كل الشهادات في المخزن التالي، مراجع الشهادات الجذر الموثوق بها. أو شغّل certutil -user -addstore Root مع مسار الملف. في macOS، أضفها إلى سلسلة مفاتيح تسجيل الدخول في الوصول إلى سلسلة المفاتيح واضبطها على الوثوق دائما. في Linux، انسخها بالامتداد .crt إلى ‎/usr/local/share/ca-certificates وشغّل update-ca-certificates.",
  "mcp.certOwnList": "يستخدم BombVault شهادته الخاصة، ويتحقق {app} من الشهادات بقائمة خاصة به لا تقبل الإضافة. إذا رفض شهادة BombVault، فاصل إلى BombVault عبر وكيل عكسي بشهادة موثوقة علنا.",
  "mcp.certOther": "يستخدم BombVault شهادته الخاصة. وجّه العميل إلى الملف الذي نزّلته، أو أضفه إلى الشهادات الموثوقة في نظامك.",
  "mcp.certOtherTip": "العميل الذي يعمل على Node.js يأخذ الملف من NODE_EXTRA_CA_CERTS. ومعظم العملاء الآخرين يستخدمون الشهادات التي يثق بها النظام. لا توقف فحص الشهادات أبدا.",
